with content as (
 select * from jsonb_to_recordset($content$[
  {"level":"A1","title":"The Seed and the Boy","body":"Kofi puts a small seed in a pot. He gives it water and puts the pot in the sun. He wants to see a plant today.\n\nThe next morning, Kofi looks at the pot. He sees only brown soil. He is sad. His grandmother says, \"The seed needs time. Give it water and wait.\"\n\nKofi gives the seed a little water every day. He does not dig it up to look at it. He plays, goes to school and does his homework.\n\nAfter some days, he sees a small green leaf. He runs to his grandmother. She smiles and says, \"You gave it water, and you gave it time.\"\n\nThe plant is still small. It is not a tree yet. Kofi looks at it every morning. He learns that waiting can be part of the work. Some good things need care and time.","summary_fr":"Kofi plante une graine et veut voir une plante immédiatement. Sa grand-mère lui apprend à l'arroser et à attendre jusqu'à l'apparition d'une petite feuille.","translation_fr":"Kofi met une petite graine dans un pot. Il lui donne de l'eau et place le pot au soleil. Il veut voir une plante aujourd'hui.\n\nLe lendemain matin, Kofi regarde le pot. Il voit seulement de la terre brune. Il est triste. Sa grand-mère dit : « La graine a besoin de temps. Donne-lui de l'eau et attends. »\n\nKofi donne un peu d'eau à la graine chaque jour. Il ne la déterre pas pour la regarder. Il joue, va à l'école et fait ses devoirs.\n\nAprès quelques jours, il voit une petite feuille verte. Il court vers sa grand-mère. Elle sourit et dit : « Tu lui as donné de l'eau et tu lui as donné du temps. »\n\nLa plante est encore petite. Ce n'est pas encore un arbre. Kofi la regarde chaque matin. Il apprend qu'attendre peut faire partie du travail. Certaines bonnes choses ont besoin de soin et de temps.","knowledge_point":"L'apprenant comprend que la patience accompagne le soin régulier et que certains résultats demandent du temps.","vocabulary":[{"word":"seed","part_of_speech":"noun","translation_fr":"graine","definition":"The small part of a plant from which a new plant grows.","example":"Kofi puts a seed in a pot."},{"word":"pot","part_of_speech":"noun","translation_fr":"pot","definition":"A container used for a plant.","example":"The pot is in the sun."},{"word":"soil","part_of_speech":"noun","translation_fr":"terre","definition":"The material in which plants grow.","example":"He sees brown soil."},{"word":"wait","part_of_speech":"verb","translation_fr":"attendre","definition":"To stay until something happens.","example":"Give the seed water and wait."},{"word":"dig up","part_of_speech":"phrasal verb","translation_fr":"déterrer","definition":"To remove something from the ground.","example":"He does not dig up the seed."},{"word":"leaf","part_of_speech":"noun","translation_fr":"feuille","definition":"A flat green part of a plant.","example":"He sees a small green leaf."},{"word":"care","part_of_speech":"noun","translation_fr":"soin","definition":"Attention that helps someone or something.","example":"Good things need care and time."},{"word":"yet","part_of_speech":"adverb","translation_fr":"encore","definition":"Used when something has not happened.","example":"It is not a tree yet."}],"questions":[{"type":"mcq","question":"Where does Kofi put the seed?","options":["In a pot","In a bag","In a book","In water only"],"answer":"In a pot","explanation_fr":"Kofi met la graine dans un pot."},{"type":"mcq","question":"What does he see the next morning?","options":["Only brown soil","A tall tree","Many flowers","A green fruit"],"answer":"Only brown soil","explanation_fr":"Aucune plante n'est encore visible."},{"type":"mcq","question":"Who gives Kofi advice?","options":["His grandmother","His teacher","His sister","His friend"],"answer":"His grandmother","explanation_fr":"Sa grand-mère lui conseille d'arroser et d'attendre."},{"type":"mcq","question":"What does Kofi do every day?","options":["Gives the seed a little water","Digs up the seed","Buys a tree","Moves the pot at night"],"answer":"Gives the seed a little water","explanation_fr":"Il donne un peu d'eau chaque jour."},{"type":"mcq","question":"What appears after some days?","options":["A small green leaf","A large tree","A red flower","A new seed only"],"answer":"A small green leaf","explanation_fr":"Une petite feuille verte apparaît."},{"type":"mcq","question":"What two things did Kofi give the seed?","options":["Water and time","Books and homework","Sun and a new pot only","Food and a bag"],"answer":"Water and time","explanation_fr":"Sa grand-mère cite l'eau et le temps."},{"type":"mcq","question":"What does Kofi learn?","options":["Waiting can be part of the work","Seeds grow in one morning","Plants need no care","Waiting means doing nothing useful"],"answer":"Waiting can be part of the work","explanation_fr":"C'est la leçon de la dernière partie."},{"type":"true_false","question":"Kofi digs up the seed every day.","options":["True","False"],"answer":"False","explanation_fr":"Il évite de la déterrer."},{"type":"true_false","question":"The plant is already a tall tree.","options":["True","False"],"answer":"False","explanation_fr":"La plante reste petite."},{"type":"open","question":"What good thing in your life needs care and time?","options":[],"answer":"Learning English needs regular practice and time, just like a seed needs water and time.","explanation_fr":"La réponse doit relier un objectif à un soin régulier et au temps."}],"grammar":[{"point":"Imperatives for advice","explanation_fr":"La base verbale seule peut donner un conseil ou une instruction.","example":"Give it water and wait."},{"point":"Present simple for habits","explanation_fr":"Le présent simple décrit les actions répétées de Kofi.","example":"He plays, goes to school and does his homework."}],"discussion":["What do you need to wait for?","How can you care for it while you wait?","Why is digging up the seed unhelpful?"]},
  {"level":"A2","title":"Learning to Wait","body":"Sonia joins a music class because she wants to play her favourite song on the keyboard. At the first lesson, she asks the teacher to teach the whole song. He agrees to show it to her, but her fingers cannot follow the different notes.\n\nSonia feels disappointed. She thinks that she is not good at music. The teacher explains that her hands are learning something new. He gives her a short exercise with only five notes and asks her to practise it slowly.\n\nDuring the first week, Sonia plays the exercise every evening. She wants to go faster, but speed creates more mistakes. She learns to listen to each note and stop when her hands become tense.\n\nIn the second week, the exercise becomes easier. Her teacher adds another short part. Sonia still cannot play the whole song, but she can hear her progress.\n\nAfter a month, she plays a simple version of the song for her family. It is slower than the original, and she makes one mistake. Her family enjoys it, and Sonia feels proud.\n\nPatience did not mean sitting and waiting for talent to appear. Sonia practised, listened and accepted that skill grows in stages. Waiting for a result became easier because she had something useful to do each day.","summary_fr":"Sonia veut jouer immédiatement une chanson au clavier. En pratiquant lentement et par étapes, elle progresse et joue une version simple un mois plus tard.","translation_fr":"Sonia s'inscrit à un cours de musique parce qu'elle veut jouer sa chanson préférée au clavier. À la première leçon, elle demande au professeur de lui apprendre toute la chanson. Il accepte de la lui montrer, mais ses doigts ne peuvent pas suivre les différentes notes.\n\nSonia est déçue. Elle pense qu'elle n'est pas douée pour la musique. Le professeur explique que ses mains apprennent quelque chose de nouveau. Il lui donne un court exercice avec seulement cinq notes et lui demande de le pratiquer lentement.\n\nPendant la première semaine, Sonia joue l'exercice chaque soir. Elle veut aller plus vite, mais la vitesse crée plus d'erreurs. Elle apprend à écouter chaque note et à s'arrêter quand ses mains deviennent tendues.\n\nDans la deuxième semaine, l'exercice devient plus facile. Son professeur ajoute une autre courte partie. Sonia ne sait toujours pas jouer toute la chanson, mais elle entend ses progrès.\n\nAprès un mois, elle joue une version simple de la chanson pour sa famille. Elle est plus lente que l'originale et elle fait une erreur. Sa famille apprécie et Sonia est fière.\n\nLa patience ne signifiait pas rester assise à attendre que le talent apparaisse. Sonia s'est entraînée, a écouté et a accepté que la compétence se développe par étapes. Attendre le résultat est devenu plus facile parce qu'elle avait quelque chose d'utile à faire chaque jour.","knowledge_point":"L'apprenant découvre que la patience active consiste à pratiquer par étapes, écouter les retours et accepter une progression graduelle.","vocabulary":[{"word":"keyboard","part_of_speech":"noun","translation_fr":"clavier","definition":"A musical instrument with black and white keys.","example":"Sonia plays the keyboard."},{"word":"note","part_of_speech":"noun","translation_fr":"note","definition":"A single musical sound or its written sign.","example":"The exercise has five notes."},{"word":"disappointed","part_of_speech":"adjective","translation_fr":"déçu","definition":"Sad because something is not as good as hoped.","example":"Sonia feels disappointed."},{"word":"slowly","part_of_speech":"adverb","translation_fr":"lentement","definition":"At a low speed.","example":"Practise the exercise slowly."},{"word":"speed","part_of_speech":"noun","translation_fr":"vitesse","definition":"How fast something happens.","example":"Speed creates more mistakes."},{"word":"tense","part_of_speech":"adjective","translation_fr":"tendu","definition":"Tight and unable to relax.","example":"Her hands become tense."},{"word":"stage","part_of_speech":"noun","translation_fr":"étape","definition":"One period in a process of development.","example":"Skill grows in stages."},{"word":"talent","part_of_speech":"noun","translation_fr":"talent","definition":"A natural ability to do something well.","example":"She does not wait for talent to appear."}],"questions":[{"type":"mcq","question":"What does Sonia want to play?","options":["Her favourite song on the keyboard","A drum rhythm","A guitar solo","A song on her phone"],"answer":"Her favourite song on the keyboard","explanation_fr":"Elle rejoint le cours pour jouer cette chanson au clavier."},{"type":"mcq","question":"Why is she disappointed?","options":["Her fingers cannot follow the notes","The teacher cancels every lesson","Her family dislikes music","The keyboard has no keys"],"answer":"Her fingers cannot follow the notes","explanation_fr":"Elle ne peut pas encore suivre les différentes notes."},{"type":"mcq","question":"How many notes are in the exercise?","options":["Five","Ten","Two","Twenty"],"answer":"Five","explanation_fr":"Le premier exercice contient cinq notes."},{"type":"mcq","question":"What happens when Sonia plays faster?","options":["She makes more mistakes","She learns immediately","Her hands relax completely","The song becomes shorter"],"answer":"She makes more mistakes","explanation_fr":"La vitesse augmente les erreurs."},{"type":"mcq","question":"What happens in the second week?","options":["The teacher adds another short part","She stops practising","She performs on stage","She forgets every note"],"answer":"The teacher adds another short part","explanation_fr":"Une nouvelle partie est ajoutée quand l'exercice devient plus facile."},{"type":"mcq","question":"What does she do after a month?","options":["Plays a simple version for her family","Plays the original perfectly","Leaves the music class","Buys a guitar"],"answer":"Plays a simple version for her family","explanation_fr":"Elle joue une version simple devant sa famille."},{"type":"mcq","question":"What made waiting easier?","options":["Having something useful to do each day","Avoiding every mistake","Playing fast every evening","Waiting for talent without practice"],"answer":"Having something useful to do each day","explanation_fr":"La pratique quotidienne donne un rôle actif à l'attente."},{"type":"true_false","question":"Sonia plays the whole song at the first lesson.","options":["True","False"],"answer":"False","explanation_fr":"Ses doigts ne peuvent pas encore suivre les notes."},{"type":"true_false","question":"Her performance after a month contains one mistake.","options":["True","False"],"answer":"True","explanation_fr":"Le texte mentionne une erreur sans empêcher sa fierté."},{"type":"open","question":"What skill could you learn slowly in stages?","options":[],"answer":"I can learn a short part first, practise it slowly, and add another part when it becomes easier.","explanation_fr":"La réponse doit présenter une progression par étapes et une pratique adaptée."}],"grammar":[{"point":"Comparative with easy","explanation_fr":"Easy devient easier au comparatif, avec y remplacé par i.","example":"The exercise becomes easier."},{"point":"Gerund as subject","explanation_fr":"La forme en ing peut être le sujet de la phrase.","example":"Waiting for a result became easier."}],"discussion":["When have you needed to learn something slowly?","Why can speed create mistakes?","What useful action can you take while waiting?"]},
  {"level":"B1","title":"Patience Is Not Doing Nothing","body":"Patience is sometimes confused with passivity. A patient person is imagined as someone who waits quietly and accepts every situation. In reality, patience often involves continued action without immediate reward.\n\nThink about learning a language. During the first weeks, new words may disappear from memory and conversations may feel slow. It is easy to conclude that the method is failing. Yet some abilities develop through repeated contact before they become easy to observe. Vocabulary needs review, listening needs practice and confidence needs experiences.\n\nPatience does not require repeating an ineffective method forever. If months pass without any useful feedback, it is reasonable to ask for help or change the approach. The difference is that you make this decision after examining evidence, not after one difficult afternoon.\n\nA helpful practice is to look for small signs of progress. Perhaps you now understand the main idea of a short audio recording, even if you miss details. Perhaps you can write a paragraph with fewer basic mistakes. These signs do not mean the work is finished. They show that your effort has a direction.\n\nPatience also helps with other people. A learner, a child or a new colleague may need time to understand instructions that seem obvious to you. Explaining something again, using an example or allowing practice can be more useful than expressing irritation.\n\nThere are moments when waiting is unwise. A dangerous situation or an unfair treatment may require prompt action. Patience should not become silence about a problem that must be addressed.\n\nUsed well, patience is the ability to give a worthwhile process enough time while staying attentive. You continue to act, observe and adjust, without demanding that every effort produce an immediate result.","summary_fr":"La patience n'est ni passive ni aveugle. Elle maintient une action utile, observe les petits progrès et ajuste la méthode sur des preuves, tout en sachant réagir quand une situation exige une intervention.","translation_fr":"La patience est parfois confondue avec la passivité. Une personne patiente est imaginée comme quelqu'un qui attend tranquillement et accepte chaque situation. En réalité, la patience implique souvent de continuer à agir sans récompense immédiate.\n\nPensez à l'apprentissage d'une langue. Pendant les premières semaines, les nouveaux mots peuvent disparaître de la mémoire et les conversations sembler lentes. Il est facile de conclure que la méthode échoue. Pourtant, certaines capacités se développent par des contacts répétés avant de devenir faciles à observer. Le vocabulaire demande des révisions, l'écoute de la pratique et la confiance des expériences.\n\nLa patience n'exige pas de répéter une méthode inefficace pour toujours. Si des mois passent sans retour utile, il est raisonnable de demander de l'aide ou de changer d'approche. La différence est que cette décision suit l'examen des preuves, pas une après-midi difficile.\n\nUne pratique utile consiste à chercher de petits signes de progrès. Peut-être comprenez-vous maintenant l'idée principale d'un court enregistrement audio, même si vous manquez des détails. Peut-être pouvez-vous écrire un paragraphe avec moins d'erreurs de base. Ces signes ne signifient pas que le travail est terminé. Ils montrent que votre effort a une direction.\n\nLa patience aide aussi avec les autres. Un apprenant, un enfant ou un nouveau collègue peut avoir besoin de temps pour comprendre des instructions qui vous semblent évidentes. Expliquer à nouveau, utiliser un exemple ou laisser du temps pour pratiquer peut être plus utile que montrer de l'irritation.\n\nIl existe des moments où attendre n'est pas sage. Une situation dangereuse ou un traitement injuste peut exiger une action rapide. La patience ne doit pas devenir un silence face à un problème qui doit être traité.\n\nBien utilisée, la patience est la capacité à donner à un processus valable assez de temps tout en restant attentif. Vous continuez à agir, observer et ajuster, sans exiger que chaque effort produise un résultat immédiat.","knowledge_point":"L'apprenant distingue patience active, passivité et persistance aveugle, en utilisant les signes de progrès et les retours pour ajuster son action.","vocabulary":[{"word":"passivity","part_of_speech":"noun","translation_fr":"passivité","definition":"Accepting what happens without taking action.","example":"Patience is not passivity."},{"word":"reward","part_of_speech":"noun","translation_fr":"récompense","definition":"A benefit received after an action.","example":"Patience can involve action without immediate reward."},{"word":"conclude","part_of_speech":"verb","translation_fr":"conclure","definition":"To decide after thinking about evidence.","example":"Do not conclude too quickly that the method fails."},{"word":"feedback","part_of_speech":"noun","translation_fr":"retour","definition":"Information about performance or results.","example":"Ask for help if there is no useful feedback."},{"word":"sign","part_of_speech":"noun","translation_fr":"signe","definition":"Something showing that a change is happening.","example":"Look for small signs of progress."},{"word":"obvious","part_of_speech":"adjective","translation_fr":"évident","definition":"Easy to see or understand.","example":"Instructions may seem obvious to you."},{"word":"irritation","part_of_speech":"noun","translation_fr":"irritation","definition":"A feeling of being annoyed.","example":"Avoid expressing irritation too quickly."},{"word":"address","part_of_speech":"verb","translation_fr":"traiter","definition":"To give attention to a problem.","example":"Some problems must be addressed promptly."}],"questions":[{"type":"mcq","question":"What is patience often confused with?","options":["Passivity","Practice","Feedback","Prompt action"],"answer":"Passivity","explanation_fr":"Le premier paragraphe distingue patience et passivité."},{"type":"mcq","question":"What can patience involve?","options":["Continued action without immediate reward","Accepting every situation","Avoiding all practice","Demanding instant results"],"answer":"Continued action without immediate reward","explanation_fr":"La patience peut demander de poursuivre un processus utile."},{"type":"mcq","question":"When is changing approach reasonable?","options":["After months without useful feedback","After one difficult afternoon","After every new word is forgotten","Before examining evidence"],"answer":"After months without useful feedback","explanation_fr":"Une décision réfléchie repose sur une absence durable de retour utile."},{"type":"mcq","question":"Which is a small sign of language progress?","options":["Understanding the main idea of a short recording","Never forgetting a word","Speaking without any preparation","Finishing all learning"],"answer":"Understanding the main idea of a short recording","explanation_fr":"Comprendre l'idée principale est un signe même si des détails manquent."},{"type":"mcq","question":"How can you help a new colleague patiently?","options":["Explain again and allow practice","Express irritation","Assume every instruction is obvious","Refuse to give examples"],"answer":"Explain again and allow practice","explanation_fr":"Le texte propose de réexpliquer, illustrer et laisser pratiquer."},{"type":"mcq","question":"When can waiting be unwise?","options":["When a situation is dangerous or unfair","When a skill develops slowly","When feedback is useful","When progress appears gradually"],"answer":"When a situation is dangerous or unfair","explanation_fr":"Ces situations peuvent demander une action rapide."},{"type":"mcq","question":"Which actions define patience used well?","options":["Act, observe and adjust","Wait, ignore and accept","Repeat, blame and stop","Demand, rush and judge"],"answer":"Act, observe and adjust","explanation_fr":"La conclusion associe ces trois actions."},{"type":"true_false","question":"Patience means repeating an ineffective method forever.","options":["True","False"],"answer":"False","explanation_fr":"Il faut pouvoir changer d'approche après examen."},{"type":"true_false","question":"Small signs can show that effort has a direction.","options":["True","False"],"answer":"True","explanation_fr":"Ils indiquent une progression sans signifier que tout est terminé."},{"type":"open","question":"Describe a situation that needs patient action and one sign you will observe.","options":[],"answer":"I will keep practising listening and observe whether I understand more main ideas, while changing the method if feedback remains absent.","explanation_fr":"La réponse doit inclure une action continue et un signe observable."}],"grammar":[{"point":"Comparative with few","explanation_fr":"Few devient fewer devant un nom pluriel dénombrable.","example":"You can write a paragraph with fewer basic mistakes."},{"point":"Without plus ing","explanation_fr":"Without suivi d'un verbe en ing indique une action qui n'a pas lieu.","example":"Patience involves acting without demanding an immediate result."}],"discussion":["How do you distinguish patience from passivity?","Which small signs show your progress?","When should patience give way to prompt action?"]},
  {"level":"B2","title":"The Discipline of Delayed Results","body":"Many worthwhile processes produce results later than the effort they require. Preparing for a qualification, improving health or building a trusted professional reputation can involve weeks of work before the outcome becomes visible. This delay creates a practical problem: the activities that matter most may offer the least immediate satisfaction.\n\nOne response is to judge every day by its visible result. If no improvement appears, the method seems pointless. Another response is to ignore results completely and continue simply because quitting feels uncomfortable. Neither approach is sufficient. Patience needs both commitment and observation.\n\nA useful review separates three questions. Are you performing the agreed action? Is the method producing any relevant signs of learning? Does the original goal still deserve the time and resources required? These questions prevent impatience from ending a useful process too early, but they also prevent loyalty to a method from replacing evidence.\n\nDelayed results can also distort memory. People may remember the final breakthrough and forget the ordinary practice that made it possible. Keeping a simple record helps correct this impression. A dated piece of writing, an earlier recording or a list of completed sessions provides something to compare with the present.\n\nThere is an emotional discipline involved as well. When progress is slow, it is tempting to seek a new plan because novelty feels like movement. Changing methods can be valuable, but frequent changes may prevent any method from producing useful evidence. The decision should come from a review, not merely from boredom.\n\nPatience does not guarantee that every project will succeed. It gives a well-chosen process enough time to reveal what it can do. During that time, you remain responsible for the quality of your effort, the accuracy of your observations and the wisdom of your adjustments. The result may be delayed, but your engagement with the process is happening now.","summary_fr":"Face à des résultats différés, la patience associe engagement, preuves et révision. Les traces de progression évitent les décisions guidées par l'ennui ou le seul résultat visible du jour.","translation_fr":"De nombreux processus valables produisent leurs résultats plus tard que l'effort qu'ils exigent. Préparer un diplôme, améliorer sa santé ou construire une réputation professionnelle fiable peut demander des semaines de travail avant que le résultat devienne visible. Ce délai crée un problème pratique : les activités les plus importantes peuvent offrir le moins de satisfaction immédiate.\n\nUne réaction consiste à juger chaque jour selon son résultat visible. Si aucune amélioration n'apparaît, la méthode semble inutile. Une autre consiste à ignorer complètement les résultats et continuer simplement parce qu'abandonner semble désagréable. Aucune de ces approches ne suffit. La patience a besoin d'engagement et d'observation.\n\nUn bilan utile sépare trois questions. Réalisez-vous l'action convenue ? La méthode produit-elle des signes pertinents d'apprentissage ? L'objectif initial mérite-t-il encore le temps et les ressources nécessaires ? Ces questions empêchent l'impatience de terminer trop tôt un processus utile, mais aussi la fidélité à une méthode de remplacer les preuves.\n\nLes résultats différés peuvent aussi déformer la mémoire. Les gens peuvent se souvenir de la réussite finale et oublier la pratique ordinaire qui l'a rendue possible. Garder une trace simple aide à corriger cette impression. Un texte daté, un ancien enregistrement ou une liste de séances terminées offre une comparaison avec le présent.\n\nIl existe aussi une discipline émotionnelle. Quand le progrès est lent, il est tentant de chercher un nouveau plan parce que la nouveauté donne l'impression d'avancer. Changer de méthode peut être utile, mais des changements fréquents peuvent empêcher toute méthode de produire des preuves. La décision doit venir d'un bilan, pas seulement de l'ennui.\n\nLa patience ne garantit pas la réussite de chaque projet. Elle donne à un processus bien choisi assez de temps pour révéler ce qu'il peut faire. Pendant ce temps, vous restez responsable de la qualité de votre effort, de la précision de vos observations et de la pertinence de vos ajustements. Le résultat peut être différé, mais votre engagement dans le processus se déroule maintenant.","knowledge_point":"L'apprenant apprend à soutenir un processus à résultat différé grâce à des preuves datées, des bilans distincts et des ajustements réfléchis.","vocabulary":[{"word":"delayed","part_of_speech":"adjective","translation_fr":"différé","definition":"Happening later than expected or desired.","example":"Many processes produce delayed results."},{"word":"qualification","part_of_speech":"noun","translation_fr":"diplôme, qualification","definition":"An official recognition of knowledge or skill.","example":"Prepare for a qualification."},{"word":"pointless","part_of_speech":"adjective","translation_fr":"inutile","definition":"Having no useful purpose.","example":"Without visible progress, the method seems pointless."},{"word":"commitment","part_of_speech":"noun","translation_fr":"engagement","definition":"A decision to give time and effort to something.","example":"Patience needs commitment and observation."},{"word":"breakthrough","part_of_speech":"noun","translation_fr":"percée","definition":"An important sudden improvement or discovery.","example":"People remember the final breakthrough."},{"word":"novelty","part_of_speech":"noun","translation_fr":"nouveauté","definition":"The quality of being new and different.","example":"Novelty can feel like movement."},{"word":"boredom","part_of_speech":"noun","translation_fr":"ennui","definition":"The state of feeling tired because nothing interests you.","example":"Do not change methods merely from boredom."},{"word":"engagement","part_of_speech":"noun","translation_fr":"engagement, implication","definition":"Active involvement in an activity.","example":"Your engagement is happening now."}],"questions":[{"type":"mcq","question":"What problem do delayed results create?","options":["Important activities may offer little immediate satisfaction","Every result becomes visible early","Effort is no longer necessary","All methods become equally useful"],"answer":"Important activities may offer little immediate satisfaction","explanation_fr":"Le décalage entre effort et résultat peut réduire la motivation."},{"type":"mcq","question":"Why is judging only each day's visible result insufficient?","options":["Useful development may not yet be visible","Every day has a final breakthrough","Methods never need review","Evidence is always immediate"],"answer":"Useful development may not yet be visible","explanation_fr":"L'absence de résultat quotidien ne prouve pas l'échec."},{"type":"mcq","question":"What is the risk of ignoring results completely?","options":["Loyalty to a method can replace evidence","Impatience ends every process early","Memory becomes more accurate","Novelty disappears"],"answer":"Loyalty to a method can replace evidence","explanation_fr":"Continuer sans observer peut maintenir une méthode inutile."},{"type":"mcq","question":"Which question belongs in a useful review?","options":["Does the goal still deserve the required resources?","Did every day produce a visible result?","Is novelty always better?","Should all evidence be ignored?"],"answer":"Does the goal still deserve the required resources?","explanation_fr":"Le bilan examine aussi la valeur actuelle de l'objectif."},{"type":"mcq","question":"How does a dated recording help?","options":["It allows comparison with the present","It guarantees a breakthrough","It removes the need for practice","It makes every method effective"],"answer":"It allows comparison with the present","explanation_fr":"Une trace ancienne rend les changements plus visibles."},{"type":"mcq","question":"Why can frequent method changes be harmful?","options":["No method has time to produce useful evidence","They always create boredom","They make observation unnecessary","They guarantee immediate results"],"answer":"No method has time to produce useful evidence","explanation_fr":"Changer trop souvent empêche d'évaluer correctement."},{"type":"mcq","question":"What remains your responsibility while results are delayed?","options":["Effort, observation and adjustment","Guaranteeing success","Avoiding every review","Seeking novelty every day"],"answer":"Effort, observation and adjustment","explanation_fr":"Ces trois responsabilités structurent l'engagement actuel."},{"type":"true_false","question":"Patience guarantees that every project will succeed.","options":["True","False"],"answer":"False","explanation_fr":"Le texte refuse explicitement cette garantie."},{"type":"true_false","question":"Changing methods should result only from boredom.","options":["True","False"],"answer":"False","explanation_fr":"La décision doit venir d'un bilan et non du seul ennui."},{"type":"open","question":"What record could help you evaluate a long-term goal fairly?","options":[],"answer":"I can keep dated recordings and completed-session notes, then review both the action and the quality of progress before changing methods.","explanation_fr":"La réponse doit décrire une trace comparable et un bilan fondé sur des preuves."}],"grammar":[{"point":"Comparative with little","explanation_fr":"Little devient less pour comparer une quantité indénombrable.","example":"Important activities may offer the least immediate satisfaction."},{"point":"Not merely for limitation","explanation_fr":"Not merely signale qu'un motif ou un facteur ne suffit pas à lui seul.","example":"The decision should come from a review, not merely from boredom."}],"discussion":["Which goal produces delayed results for you?","What record would reveal gradual progress?","When should boredom lead to a review rather than a change?"]},
  {"level":"C1","title":"Patience Without Passivity","body":"Patience has an image problem. It is praised as a virtue, yet often interpreted as an instruction to tolerate delay without protest. This interpretation can serve convenience: people who are expected to wait indefinitely may appear easier to manage. Genuine patience, however, is neither submission nor the refusal to act.\n\nAt its best, patience is a way of relating to time without abandoning judgment. Some processes cannot be accelerated without damaging their quality. Trust, expertise and meaningful relationships require repeated experiences rather than declarations. Insisting on immediate proof can destroy the very conditions under which these outcomes develop.\n\nNevertheless, the passage of time is not itself evidence of progress. A difficult situation does not become acceptable simply because someone has endured it for long enough. Patience must therefore be accompanied by criteria: what is being developed, which observations would indicate movement, and which circumstances would require intervention? Without such criteria, waiting can conceal avoidance or preserve an unfair arrangement.\n\nThis distinction matters in education. A coach may allow a learner to struggle productively with a difficult sentence instead of immediately supplying the answer. The delay can support reasoning and memory. But if the learner lacks the basic knowledge required to begin, withholding all assistance merely produces confusion. Patient guidance adjusts the level of support rather than offering either instant solutions or total abandonment.\n\nThe same principle applies to personal ambitions. Impatience may provoke constant changes of direction because novelty provides the sensation of progress. Passive endurance may produce the opposite error, preserving a failing strategy to demonstrate strength of character. Reflective patience resists both impulses. It gives a sound method time to work while remaining willing to revise the method when evidence demands it.\n\nThere is also a moral limit. Patience should not be used to ask other people to absorb avoidable harm while those responsible postpone change. Waiting for a fair process is different from waiting for fairness to appear spontaneously.\n\nPatience without passivity is therefore an active discipline. It combines tolerance for gradual development with attention to evidence, appropriate support and timely intervention. Its question is not simply how long you can wait, but how wisely you can remain engaged while time does its part.","summary_fr":"La patience véritable n'est ni soumission ni attente aveugle. Elle donne du temps aux processus graduels tout en utilisant des critères, un soutien adapté et une intervention quand les preuves ou la justice l'exigent.","translation_fr":"La patience a un problème d'image. Elle est louée comme une vertu, mais souvent interprétée comme une instruction à tolérer le délai sans protester. Cette interprétation peut servir la commodité : les personnes censées attendre indéfiniment semblent plus faciles à gérer. La véritable patience, cependant, n'est ni soumission ni refus d'agir.\n\nDans sa meilleure forme, la patience est une manière de se rapporter au temps sans abandonner son jugement. Certains processus ne peuvent être accélérés sans nuire à leur qualité. La confiance, l'expertise et les relations significatives exigent des expériences répétées plutôt que des déclarations. Insister sur une preuve immédiate peut détruire les conditions mêmes dans lesquelles ces résultats se développent.\n\nNéanmoins, le passage du temps n'est pas en soi une preuve de progrès. Une situation difficile ne devient pas acceptable simplement parce qu'elle a été supportée assez longtemps. La patience doit donc s'accompagner de critères : qu'est-ce qui se développe, quelles observations indiqueraient un mouvement et quelles circonstances exigeraient une intervention ? Sans ces critères, attendre peut cacher un évitement ou préserver une organisation injuste.\n\nCette distinction compte dans l'éducation. Un coach peut laisser un apprenant lutter de façon productive avec une phrase difficile au lieu de fournir immédiatement la réponse. Ce délai peut soutenir le raisonnement et la mémoire. Mais si l'apprenant ne possède pas les connaissances de base nécessaires pour commencer, refuser toute aide produit seulement de la confusion. Un accompagnement patient ajuste le niveau de soutien au lieu d'offrir soit des solutions instantanées, soit un abandon total.\n\nLe même principe s'applique aux ambitions personnelles. L'impatience peut provoquer des changements constants de direction parce que la nouveauté donne une sensation de progrès. L'endurance passive peut produire l'erreur opposée, préservant une stratégie qui échoue pour démontrer la force du caractère. La patience réfléchie résiste à ces deux impulsions. Elle donne à une méthode solide le temps de fonctionner tout en acceptant de la réviser lorsque les preuves l'exigent.\n\nIl existe aussi une limite morale. La patience ne doit pas servir à demander aux autres d'absorber un dommage évitable pendant que les responsables reportent le changement. Attendre qu'un processus équitable se déroule diffère d'attendre que l'équité apparaisse spontanément.\n\nLa patience sans passivité est donc une discipline active. Elle associe la tolérance au développement graduel, l'attention aux preuves, un soutien approprié et une intervention au bon moment. Sa question n'est pas simplement combien de temps on peut attendre, mais avec quelle sagesse on peut rester engagé pendant que le temps fait sa part.","knowledge_point":"L'apprenant analyse la patience comme discipline active et morale, fondée sur des critères, un soutien adapté et une intervention responsable.","vocabulary":[{"word":"submission","part_of_speech":"noun","translation_fr":"soumission","definition":"Accepting another person's control without resistance.","example":"Genuine patience is not submission."},{"word":"accelerate","part_of_speech":"verb","translation_fr":"accélérer","definition":"To make something happen faster.","example":"Some processes cannot be accelerated safely."},{"word":"intervention","part_of_speech":"noun","translation_fr":"intervention","definition":"Action taken to improve or change a situation.","example":"Some circumstances require intervention."},{"word":"withhold","part_of_speech":"verb","translation_fr":"retenir, ne pas donner","definition":"To refuse to give something.","example":"Withholding all assistance produces confusion."},{"word":"productive struggle","part_of_speech":"noun phrase","translation_fr":"effort productif","definition":"Difficulty that supports learning at an appropriate level.","example":"A learner can engage in productive struggle."},{"word":"endurance","part_of_speech":"noun","translation_fr":"endurance","definition":"Continuing through difficulty over time.","example":"Passive endurance can preserve a failing strategy."},{"word":"avoidable","part_of_speech":"adjective","translation_fr":"évitable","definition":"Possible to prevent.","example":"People should not absorb avoidable harm."},{"word":"spontaneously","part_of_speech":"adverb","translation_fr":"spontanément","definition":"Happening without being planned or caused deliberately.","example":"Fairness may not appear spontaneously."}],"questions":[{"type":"mcq","question":"How is patience sometimes misinterpreted?","options":["As tolerating delay without protest","As active judgment","As appropriate support","As timely intervention"],"answer":"As tolerating delay without protest","explanation_fr":"Cette interprétation réduit la patience à la passivité."},{"type":"mcq","question":"Which outcomes require repeated experiences?","options":["Trust, expertise and meaningful relationships","Instant declarations only","Avoidable harm","Constant novelty"],"answer":"Trust, expertise and meaningful relationships","explanation_fr":"Ces résultats se développent dans le temps."},{"type":"mcq","question":"Why is time alone not evidence of progress?","options":["A situation can remain unchanged or unfair despite endurance","Every delay improves quality","All methods succeed eventually","Observation becomes unnecessary"],"answer":"A situation can remain unchanged or unfair despite endurance","explanation_fr":"La durée ne garantit ni développement ni justice."},{"type":"mcq","question":"Which criterion supports reflective patience?","options":["Observations that would indicate movement","Waiting without any purpose","Avoiding all intervention","Judging only personal strength"],"answer":"Observations that would indicate movement","explanation_fr":"Des signes observables permettent d'évaluer le processus."},{"type":"mcq","question":"When can delaying an answer help a learner?","options":["When productive struggle supports reasoning","When basic knowledge is entirely absent","When confusion is the goal","When all support is withheld"],"answer":"When productive struggle supports reasoning","explanation_fr":"Un défi adapté peut laisser le temps de raisonner."},{"type":"mcq","question":"What should patient guidance adjust?","options":["The level of support","The learner's personal worth","The need for evidence","Every learning goal"],"answer":"The level of support","explanation_fr":"Le coach adapte l'aide au lieu de tout donner ou tout refuser."},{"type":"mcq","question":"Which opposite errors does reflective patience resist?","options":["Constant novelty and passive endurance","Evidence and support","Gradual development and review","Action and judgment"],"answer":"Constant novelty and passive endurance","explanation_fr":"Elle évite à la fois les changements impulsifs et l'entêtement passif."},{"type":"true_false","question":"Patience should require others to absorb avoidable harm.","options":["True","False"],"answer":"False","explanation_fr":"Le texte fixe une limite morale à l'attente."},{"type":"true_false","question":"Reflective patience can revise a method when evidence demands it.","options":["True","False"],"answer":"True","explanation_fr":"Elle donne du temps sans refuser la révision."},{"type":"open","question":"Describe a situation requiring patient engagement and a condition for intervention.","options":[],"answer":"I can give a learner time to reason, observe their attempts, and intervene with a hint if they lack the knowledge needed to begin.","explanation_fr":"La réponse doit associer attente active, observation et seuil d'intervention."}],"grammar":[{"point":"Neither for exclusion","explanation_fr":"Neither relie deux définitions rejetées dans une formulation concise.","example":"Genuine patience is neither submission nor the refusal to act."},{"point":"Not simply but for emphasis","explanation_fr":"Cette structure déplace l'attention d'une question superficielle vers une question plus pertinente.","example":"Its question is not simply how long you can wait, but how wisely you can remain engaged."}],"discussion":["When can waiting preserve an unfair situation?","How does productive struggle differ from confusion?","Which criteria help you remain patient without becoming passive?"]}
 ]$content$::jsonb) as x(level public.rw_level,title text,body text,summary_fr text,translation_fr text,knowledge_point text,vocabulary jsonb,questions jsonb,grammar jsonb,discussion jsonb)
)
insert into public.rw_lessons(session_id,level,title,body,word_count,summary_fr,translation_fr,knowledge_point,vocabulary,questions,grammar,discussion,mention,status,content_type,rights_status,published_at)
select s.id,c.level,c.title,c.body,cardinality(regexp_split_to_array(btrim(c.body),'[[:space:]]+')),
 c.summary_fr,c.translation_fr,c.knowledge_point,c.vocabulary,c.questions,c.grammar,c.discussion,
 'original','published','original text','Texte original OpenDoorsClass',now()
from content c join public.rw_weeks w on w.week_number=4 join public.rw_sessions s on s.week_id=w.id and s.day_index=4
on conflict(session_id,level) do update set title=excluded.title,body=excluded.body,word_count=excluded.word_count,
 summary_fr=excluded.summary_fr,translation_fr=excluded.translation_fr,knowledge_point=excluded.knowledge_point,
 vocabulary=excluded.vocabulary,questions=excluded.questions,grammar=excluded.grammar,discussion=excluded.discussion,
 mention='original',status='published',content_type='original text',rights_status='Texte original OpenDoorsClass',
 published_at=coalesce(rw_lessons.published_at,now()) where rw_lessons.status<>'published';
do $$ declare invalid_count integer; begin
 select count(*) into invalid_count from public.rw_lessons l join public.rw_sessions s on s.id=l.session_id
 join public.rw_weeks w on w.id=s.week_id where w.week_number=4 and s.day_index=4 and
 (l.status<>'published' or jsonb_array_length(l.questions)<>10 or jsonb_array_length(l.vocabulary)<8
 or jsonb_array_length(l.grammar)<>2 or jsonb_array_length(l.discussion)<>3 or l.body='' or coalesce(l.translation_fr,'')='');
 if invalid_count<>0 then raise exception 'Validation impossible: % leçons incomplètes',invalid_count; end if;
end $$;